import{_ as h,o as t,c as i,a2 as c}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"Cơ cấu Xã hội và Lưu động Giai cấp","description":"","frontmatter":{},"headers":[],"relativePath":"vi/36-社会结构与阶层流动.md","filePath":"vi/36-社会结构与阶层流动.md","lastUpdated":null}'),g={name:"vi/36-社会结构与阶层流动.md"};function a(u,n,o,l,r,p){return t(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="co-cau-xa-hoi-va-luu-đong-giai-cap" tabindex="-1">Cơ cấu Xã hội và Lưu động Giai cấp <a class="header-anchor" href="#co-cau-xa-hoi-va-luu-đong-giai-cap" aria-label="Permalink to &quot;Cơ cấu Xã hội và Lưu động Giai cấp&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>36</td></tr><tr><td>Mô-đun</td><td>Kiểu hình Văn minh và Hệ thống Xã hội</td></tr><tr><td>Từ khóa chính</td><td>Cơ cấu Xã hội, Lưu động Giai cấp, Hệ thống Mở, Thăng tiến Công bằng, Chống Đóng băng</td></tr></tbody></table><h2 id="_1-khai-niem-co-ban-ve-co-cau-xa-hoi-va-su-theo-đuoi-cua-van-minh-cong-sinh" tabindex="-1">1. Khái niệm Cơ bản về Cơ cấu Xã hội và Sự Theo đuổi của Văn minh Cộng sinh <a class="header-anchor" href="#_1-khai-niem-co-ban-ve-co-cau-xa-hoi-va-su-theo-đuoi-cua-van-minh-cong-sinh" aria-label="Permalink to &quot;1. Khái niệm Cơ bản về Cơ cấu Xã hội và Sự Theo đuổi của Văn minh Cộng sinh&quot;">​</a></h2><p>Cơ cấu xã hội đề cập đến cách tổ chức và mô hình quan hệ giữa các nhóm khác nhau trong một xã hội, bao gồm nhiều chiều như phân chia giai cấp, phân chia vai trò, phân bổ quyền lực, phân bổ nguồn lực, v.v. Trong bất kỳ hình thức văn minh nào, cơ cấu xã hội đều ảnh hưởng sâu sắc đến cơ hội phát triển của cá nhân, hiệu quả vận hành của xã hội và sự ổn định dài hạn của văn minh.</p><p>Trong thời đại hệ thống tu luyện cướp bóc, cơ cấu xã hội thể hiện sự đóng băng và bất bình đẳng cực đoan: giữa người mạnh và người yếu tồn tại một hố sâu không thể vượt qua, xuất thân quyết định số phận, và các sinh vật tầng đáy gần như không có khả năng lưu động lên trên. Cơ cấu xã hội đóng băng này không chỉ gây ra đau khổ vô tận, mà còn dẫn đến mất sức sống xã hội và trì trệ văn minh — tiềm năng của đại đa số cá nhân bị lãng phí, và ít người có lợi ích đã đạt được, để duy trì đặc quyền, không ngần ngại kìm hãm đổi mới và tiến bộ.</p><p>Sau khi văn minh cộng sinh neo được thành lập, việc xây dựng cơ cấu xã hội &quot;mở, lưu động, công bằng, đầy sức sống&quot; được coi là một trong những mục tiêu cốt lõi. Văn minh cộng sinh tin chắc: một cơ cấu xã hội lành mạnh phải cho phép mỗi cá nhân thay đổi số phận thông qua nỗ lực của chính mình, phải để nguồn lực xã hội chảy về người có năng lực nhất và đóng góp nhiều nhất, và phải duy trì các kênh lưu động thông suốt giữa các giai cấp khác nhau. Chỉ như vậy, tính tích cực và sáng tạo của toàn bộ sinh vật cộng sinh mới có thể được khơi dậy đầy đủ, và mục tiêu vĩ đại của tiến bộ chung của mọi chủng tộc mới có thể được实现.</p><p>Sự theo đuổi cốt lõi của cơ cấu xã hội văn minh cộng sinh có thể được tóm tắt trong bốn câu:</p><ol><li><strong>Mở và Bao hàm</strong>: Xã hội mở cửa cho tất cả các cá nhân, và không đặt ra rào cản tiếp cận do các yếu tố như chủng tộc, xuất thân, giới tính, v.v.</li><li><strong>Lưu động Thông suốt</strong>: Duy trì các kênh lưu động thông suốt giữa các giai cấp khác nhau, và cá nhân có thể实现 lưu động lên trên thông qua nỗ lực</li><li><strong>Công bằng và Chính nghĩa</strong>: Phân bổ nguồn lực và cung cấp cơ hội tuân theo nguyên tắc công bằng, và mỗi cá nhân đều có cơ hội phát triển bình đẳng</li><li><strong>Đầy Sức sống</strong>: Cơ cấu xã hội có thể khơi dậy tính tích cực và sáng tạo của cá nhân, và duy trì sức sống phát triển dồi dào</li></ol><h2 id="_2-phan-chia-giai-cap-xa-hoi-cua-van-minh-cong-sinh" tabindex="-1">2. Phân chia Giai cấp Xã hội của Văn minh Cộng sinh <a class="header-anchor" href="#_2-phan-chia-giai-cap-xa-hoi-cua-van-minh-cong-sinh" aria-label="Permalink to &quot;2. Phân chia Giai cấp Xã hội của Văn minh Cộng sinh&quot;">​</a></h2><p>Phân chia giai cấp xã hội của văn minh cộng sinh không lấy xuất thân, chủng tộc, của cải làm tiêu chuẩn, mà lấy &quot;độ cộng sinh&quot; và &quot;cảnh giới tu luyện&quot; làm tham chiếu cốt lõi, hình thành một hệ thống giai cấp động và mở:</p><table tabindex="0"><thead><tr><th>Giai cấp</th><th>Tên</th><th>Tỷ lệ</th><th>Đặc điểm cốt lõi</th><th>Trách nhiệm chính</th></tr></thead><tbody><tr><td>Lớp thứ nhất</td><td>Người dẫn dắt Cộng sinh</td><td>Khoảng 1%</td><td>Người mạnh tối cao ở位面, độ cộng sinh cấp S, người dẫn dắt cốt lõi của văn minh</td><td>Quyết định chiến lược, duy trì pháp luật, quản lý xuyên位面</td></tr><tr><td>Lớp thứ hai</td><td>Xương sống Cộng sinh</td><td>Khoảng 5%</td><td>Người tu luyện cấp cao, độ cộng sinh cấp A, lực lượng xương sống của mọi lĩnh vực</td><td>Nghiên cứu và phát triển công nghệ, quản lý tổ chức, đào tạo nhân tài</td></tr><tr><td>Lớp thứ ba</td><td>Người làm nghề Cộng sinh</td><td>Khoảng 20%</td><td>Người tu luyện cấp trung, độ cộng sinh cấp B, nhân tài chuyên môn của mọi ngành</td><td>Dịch vụ chuyên môn, ứng dụng công nghệ, quản lý tầng đáy</td></tr><tr><td>Lớp thứ tư</td><td>Đại chúng Cộng sinh</td><td>Khoảng 60%</td><td>Người tu luyện cấp sơ cấp, độ cộng sinh cấp C, lực lượng cơ bản của văn minh</td><td>Tu luyện cơ bản, dịch vụ sản xuất, tham gia cộng đồng</td></tr><tr><td>Lớp thứ năm</td><td>Người mới Cộng sinh</td><td>Khoảng 14%</td><td>Vừa mới nhập môn hoặc đang chờ cải thiện, độ cộng sinh cấp D, cần sự giúp đỡ và hướng dẫn</td><td>Học tập và trưởng thành, tiếp nhận hướng dẫn, từng bước hòa nhập</td></tr></tbody></table><p>Cần đặc biệt nhấn mạnh rằng, sự phân chia giai cấp này không cố định bất biến, mà là động và có thể lưu động. Mỗi cá nhân đều có thể nâng cao độ cộng sinh và cảnh giới tu luyện thông qua nỗ lực của chính mình,实现 sự thăng tiến giai cấp; ngược lại, nếu cá nhân không có ý chí tiến thủ hoặc thậm chí vi phạm đạo đức cộng sinh, sự sụt giảm giai cấp cũng có thể xảy ra.</p><p>Ngoài ra, sự phân chia giai cấp không có nghĩa là đặc quyền và phân biệt đối xử. Cá nhân ở mỗi giai cấp đều được hưởng các quyền cơ bản bình đẳng và phẩm giá con người bình đẳng, và sự khác biệt về giai cấp chủ yếu thể hiện ở phân chia trách nhiệm và phân bổ nguồn lực, chứ không phải ở sự cao thấp của phẩm giá con người.</p><h2 id="_3-co-che-va-kenh-luu-đong-giai-cap" tabindex="-1">3. Cơ chế và Kênh Lưu động Giai cấp <a class="header-anchor" href="#_3-co-che-va-kenh-luu-đong-giai-cap" aria-label="Permalink to &quot;3. Cơ chế và Kênh Lưu động Giai cấp&quot;">​</a></h2><p>Văn minh cộng sinh đã thiết lập cơ chế lưu động giai cấp đa kênh, đa tầng, đảm bảo rằng mỗi cá nhân đều có cơ hội实现 lưu động lên trên thông qua nỗ lực của chính mình:</p><h3 id="_3-1-kenh-thang-tien-tu-luyen" tabindex="-1">3.1 Kênh Thăng tiến Tu luyện <a class="header-anchor" href="#_3-1-kenh-thang-tien-tu-luyen" aria-label="Permalink to &quot;3.1 Kênh Thăng tiến Tu luyện&quot;">​</a></h3><p>Thăng tiến tu luyện là kênh lưu động giai cấp chính yếu nhất. Văn minh cộng sinh, thông qua việc mở ba trăm hệ thống tu luyện bản nguyên, đã cung cấp cho mỗi cá nhân một con đường thăng tiến tu luyện rõ ràng:</p><ul><li><strong>Thăng tiến Cảnh giới</strong>: Người tu luyện nâng cao cảnh giới thông qua tu luyện, từ sơ cấp lên trung cấp, cao cấp, tối cao, và mỗi lần đột phá cảnh giới đều có thể mang lại sự thăng tiến giai cấp</li><li><strong>Đột phá Hệ thống</strong>: Người tu luyện đạt được kết quả đột phá trong một hệ thống tu luyện nhất định, có thể获得 sự nâng cao độ cộng sinh và sự thăng tiến giai cấp</li><li><strong>Đổi mới Công nghệ</strong>: Người tu luyện đạt được kết quả đổi mới trong lĩnh vực công nghệ tu luyện, công nghệ kỹ thuật, v.v., có thể获得 vinh dự và thưởng nguồn lực, thúc đẩy sự thăng tiến giai cấp</li></ul><p>Nguyên tắc cốt lõi của kênh thăng tiến tu luyện là &quot;ai cũng có con đường&quot; — bất kể xuất thân như thế nào, miễn là nỗ lực tu luyện, đều có cơ hội实现 sự thăng tiến giai cấp.</p><h3 id="_3-2-kenh-thang-tien-đong-gop" tabindex="-1">3.2 Kênh Thăng tiến Đóng góp <a class="header-anchor" href="#_3-2-kenh-thang-tien-đong-gop" aria-label="Permalink to &quot;3.2 Kênh Thăng tiến Đóng góp&quot;">​</a></h3><p>Ngoài cảnh giới tu luyện, đóng góp cho văn minh cộng sinh cũng là cơ sở quan trọng của lưu động giai cấp:</p><ul><li><strong>Đóng góp Dịch vụ Công cộng</strong>: Tham gia các dịch vụ công cộng như bảo trì neo, hướng dẫn cố vấn, cứu hộ khẩn cấp, v.v., tích lũy giá trị đóng góp</li><li><strong>Đóng góp Nghiên cứu và Phát triển Công nghệ</strong>: Đóng góp nghiên cứu và phát triển trong lĩnh vực công nghệ tu luyện, công nghệ kỹ thuật, v.v.</li><li><strong>Đóng góp Truyền bá Văn hóa</strong>: Truyền bá triết lý cộng sinh, sáng tác tác phẩm văn hóa, thúc đẩy trao đổi văn minh</li><li><strong>Đóng góp Tham gia Quản trị</strong>: Tham gia quản lý xã hội, đề xuất đề xuất chính sách, thúc đẩy tối ưu hóa hệ thống</li></ul><p>Nguyên tắc cốt lõi của kênh thăng tiến đóng góp là &quot;làm nhiều được nhiều&quot; — đóng góp cho văn minh cộng sinh càng lớn, phần thưởng và sự thăng tiến giai cấp nhận được càng nhiều.</p><h3 id="_3-3-kenh-thang-tien-giao-duc" tabindex="-1">3.3 Kênh Thăng tiến Giáo dục <a class="header-anchor" href="#_3-3-kenh-thang-tien-giao-duc" aria-label="Permalink to &quot;3.3 Kênh Thăng tiến Giáo dục&quot;">​</a></h3><p>Giáo dục là bậc thang quan trọng của lưu động giai cấp. Văn minh cộng sinh đã thiết lập hệ thống thăng tiến giáo dục hoàn chỉnh:</p><ul><li><strong>Giáo dục Cơ bản</strong>: Cung cấp giáo dục tu luyện cơ bản miễn phí cho mỗi cá nhân, đảm bảo công bằng điểm khởi đầu</li><li><strong>Giáo dục Nâng cao</strong>: Thông qua kiểm tra, tuyển chọn học viên xuất sắc vào học viện tu luyện nâng cao, nhận được đào tạo trình độ cao hơn</li><li><strong>Giáo dục Tinh anh</strong>: Tuyển chọn cá nhân có tiềm năng nhất vào kế hoạch đào tạo tinh anh, nhận được sự hỗ trợ nguồn lực cấp cao nhất</li><li><strong>Giáo dục Trọn đời</strong>: Cung cấp cơ hội học tập và nâng cao liên tục cho cá nhân ở mọi lứa tuổi</li></ul><p>Nguyên tắc cốt lõi của kênh thăng tiến giáo dục là &quot;cơ hội bình đẳng&quot; — mỗi cá nhân đều có cơ hội bình đẳng实现 sự thăng tiến giai cấp thông qua giáo dục.</p><h3 id="_3-4-kenh-thang-tien-đac-biet" tabindex="-1">3.4 Kênh Thăng tiến Đặc biệt <a class="header-anchor" href="#_3-4-kenh-thang-tien-đac-biet" aria-label="Permalink to &quot;3.4 Kênh Thăng tiến Đặc biệt&quot;">​</a></h3><p>Đối với cá nhân có đóng góp nổi bật hoặc thể hiện tài năng đặc biệt trong lĩnh vực đặc biệt, văn minh cộng sinh có các kênh thăng tiến đặc biệt:</p><ul><li><strong>Thăng tiến Đặc biệt cho Nhân tài Đặc biệt</strong>: Đối với cá nhân có thiên tài đặc biệt hoặc có đóng góp đặc biệt trong một lĩnh vực nhất định, có thể thăng tiến giai cấp một cách đặc biệt</li><li><strong>Thăng tiến vì Công lao trong Sự kiện Khẩn cấp</strong>: Cá nhân có công lao trong việc đối phó với các sự kiện khẩn cấp (như thảm họa, xâm nhập, khủng hoảng, v.v.) có thể nhận được sự thăng tiến nhanh chóng</li><li><strong>Thăng tiến vì Đóng góp Khám phá Xuyên位面</strong>: Cá nhân có đóng góp nổi bật trong khám phá và khảo cổ xuyên位面 có thể nhận được sự thăng tiến</li></ul><h2 id="_4-bao-đam-he-thong-đe-ngan-chan-đong-bang-giai-cap" tabindex="-1">4. Bảo đảm Hệ thống để Ngăn chặn Đóng băng Giai cấp <a class="header-anchor" href="#_4-bao-đam-he-thong-đe-ngan-chan-đong-bang-giai-cap" aria-label="Permalink to &quot;4. Bảo đảm Hệ thống để Ngăn chặn Đóng băng Giai cấp&quot;">​</a></h2><p>Sự thông suốt của lưu động giai cấp đòi hỏi bảo đảm hệ thống. Văn minh cộng sinh đã thiết lập các hệ thống sau đây để ngăn chặn đóng băng giai cấp:</p><h3 id="_4-1-he-thong-chong-đoc-quyen" tabindex="-1">4.1 Hệ thống Chống Độc quyền <a class="header-anchor" href="#_4-1-he-thong-chong-đoc-quyen" aria-label="Permalink to &quot;4.1 Hệ thống Chống Độc quyền&quot;">​</a></h3><p>Hiến pháp Cộng sinh và Luật Chống Độc quyền rõ ràng cấm bất kỳ tổ chức hoặc cá nhân nào độc quyền nguồn lực tu luyện, hệ thống tu luyện, cơ hội giáo dục, v.v. Hệ thống chống độc quyền ngăn chặn các nhóm lợi ích đã đạt được cố định hóa đặc quyền của mình thông qua độc quyền nguồn lực, đảm bảo sự mở và lưu động của nguồn lực.</p><h3 id="_4-2-he-thong-thue-di-san-va-thue-tang" tabindex="-1">4.2 Hệ thống Thuế Di sản và Thuế Tặng <a class="header-anchor" href="#_4-2-he-thong-thue-di-san-va-thue-tang" aria-label="Permalink to &quot;4.2 Hệ thống Thuế Di sản và Thuế Tặng&quot;">​</a></h3><p>Để ngăn chặn của cải và nguồn lực gây ra đóng băng giai cấp thông qua truyền tải thế hệ, văn minh cộng sinh thực hiện hệ thống thuế di sản và thuế tặng theo tiến trình. Di sản và tặng có giá trị ròng cao cần nộp thuế với tỷ lệ cao hơn, được đưa vào hồ chứa nguồn lực công cộng, và sử dụng cho lợi ích chung của toàn bộ sinh vật cộng sinh.</p><h3 id="_4-3-he-thong-cong-bang-giao-duc" tabindex="-1">4.3 Hệ thống Công bằng Giáo dục <a class="header-anchor" href="#_4-3-he-thong-cong-bang-giao-duc" aria-label="Permalink to &quot;4.3 Hệ thống Công bằng Giáo dục&quot;">​</a></h3><p>Văn minh cộng sinh đảm bảo công bằng giáo dục thông qua Luật Bảo đảm Giáo dục:</p><ul><li>Giáo dục cơ bản mở cửa miễn phí cho tất cả công dân</li><li>Việc tuyển chọn cho giáo dục nâng cao và giáo dục tinh anh lấy năng lực và tiềm năng làm tiêu chuẩn, không nhìn xuất thân và của cải</li><li>Cung cấp hỗ trợ giáo dục bổ sung và bồi thường cho các nhóm dễ bị tổn thương</li><li>Cấm mọi hình thức phân biệt đối xử giáo dục và đặc quyền giáo dục</li></ul><h3 id="_4-4-he-thong-giam-sat-luu-đong-giai-cap" tabindex="-1">4.4 Hệ thống Giám sát Lưu động Giai cấp <a class="header-anchor" href="#_4-4-he-thong-giam-sat-luu-đong-giai-cap" aria-label="Permalink to &quot;4.4 Hệ thống Giám sát Lưu động Giai cấp&quot;">​</a></h3><p>Lõi thông tin của mạng lưới cộng sinh giám sát tình hình lưu động giai cấp xã hội theo thời gian thực, và các chỉ số giám sát cốt lõi bao gồm:</p><ul><li><strong>Tỷ lệ Lưu động Liên thế hệ</strong>: Mức độ khác biệt giữa giai cấp con cái và giai cấp cha mẹ</li><li><strong>Tỷ lệ Lưu động Lên trên</strong>: Tỷ lệ cá nhân实现 sự thăng tiến giai cấp trong mỗi chu kỳ</li><li><strong>Tỷ lệ Lưu động Xuống dưới</strong>: Tỷ lệ cá nhân trải qua sự sụt giảm giai cấp trong mỗi chu kỳ</li><li><strong>Chỉ số Đóng băng Giai cấp</strong>: Mức độ &quot;thừa kế&quot; bên trong mỗi giai cấp</li></ul><p>Khi các chỉ số giám sát cho thấy lưu động giai cấp có hiện tượng không thông suốt hoặc xu hướng đóng băng, cơ quan quản trị sẽ kịp thời thực hiện điều chỉnh chính sách, đảm bảo sự thông suốt của lưu động giai cấp.</p><h2 id="_5-su-khac-biet-ve-co-cau-xa-hoi-giua-nam-kieu-hinh-van-minh" tabindex="-1">5. Sự Khác biệt về Cơ cấu Xã hội giữa Năm Kiểu hình Văn minh <a class="header-anchor" href="#_5-su-khac-biet-ve-co-cau-xa-hoi-giua-nam-kieu-hinh-van-minh" aria-label="Permalink to &quot;5. Sự Khác biệt về Cơ cấu Xã hội giữa Năm Kiểu hình Văn minh&quot;">​</a></h2><p>Năm kiểu hình văn minh cộng sinh có đặc điểm riêng về cơ cấu xã hội:</p><table tabindex="0"><thead><tr><th>Kiểu hình</th><th>Đặc điểm cơ cấu xã hội</th><th>Đặc điểm lưu động giai cấp</th></tr></thead><tbody><tr><td>Tập trung Đông Á</td><td>Định hướng tập thể, thứ bậc rõ ràng, dựa trên gia tộc và môn phái</td><td>Kênh lưu động chủ yếu là thăng tiến môn phái, tốc độ lưu động trung bình</td></tr><tr><td>Phúc lợi Bắc Âu</td><td>Bằng phẳng, bình đẳng cao, giai cấp yếu</td><td>Sự khác biệt giai cấp nhỏ, áp lực lưu động nhỏ, tốc độ lưu động chậm hơn</td></tr><tr><td>Đa nguyên Bắc Mỹ</td><td>Thị trường hóa, đa nguyên, cạnh tranh gay gắt</td><td>Kênh lưu động chủ yếu là cạnh tranh thị trường, tốc độ lưu động nhanh nhưng sự khác biệt lớn</td></tr><tr><td>Xã hội Lục địa Âu</td><td>Chủ nghĩa tập đoàn, quyết định chung lao động - vốn, dân chủ thương lượng</td><td>Kênh lưu động chủ yếu là năng lực nghề nghiệp và thương lượng tập thể, lưu động ổn định</td></tr><tr><td>Đuổi kịp Đang Phát triển</td><td>Chính phủ mạnh, lưu động nhanh, phát triển gradient</td><td>Tốc độ lưu động nhanh, cơ hội thăng tiến nhiều, sức sống xã hội dồi dào</td></tr></tbody></table><p>Mặc dù có sự khác biệt về cơ cấu xã hội giữa các kiểu hình, tất cả đều tuân theo các nguyên tắc cơ bản của Hiến pháp Cộng sinh, và tất cả đều cam kết xây dựng cơ cấu xã hội mở, lưu động, công bằng, đầy sức sống.</p><h2 id="loi-ket" tabindex="-1">Lời kết <a class="header-anchor" href="#loi-ket" aria-label="Permalink to &quot;Lời kết&quot;">​</a></h2><p>Cơ cấu xã hội và lưu động giai cấp là một trong những chủ đề cốt lõi của xây dựng hệ thống văn minh cộng sinh neo. Văn minh cộng sinh, thông qua việc phân chia giai cấp động lấy độ cộng sinh và cảnh giới tu luyện làm cốt lõi, cơ chế lưu động giai cấp đa kênh, và bảo đảm hệ thống để ngăn chặn đóng băng giai cấp, đã xây dựng một cơ cấu xã hội mở, lưu động, công bằng, đầy sức sống. Trong cơ cấu xã hội như vậy, mỗi cá nhân đều có thể thay đổi số phận thông qua nỗ lực của chính mình, nguồn lực xã hội có thể chảy về người có năng lực nhất và đóng góp nhiều nhất, và toàn bộ văn minh duy trì sức sống phát triển dồi dào. Đây chính là nền tảng xã hội quan trọng giúp văn minh cộng sinh实现 được tiến bộ chung của mọi chủng tộc.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>26-个体与集体平衡原理 (Nguyên lý Cân bằng giữa Cá nhân và Tập thể)</li><li>29-共生度评估体系 (Hệ thống Đánh giá Độ Cộng sinh)</li><li>30-五种共生文明分型总览 (Tổng quan về Năm Kiểu hình Văn minh Cộng sinh)</li></ul>',51)])])}const m=h(g,[["render",a]]);export{s as __pageData,m as default};
